nb.code("import pandas as pd, hashlib, gzip, json", "from pathlib import Path", "from starplast import host as H, organisms as O", "root=Path('/media/carruthers/mnt3/claude/toxoplasma_projects/datasets')", "base=Path('results/host_expression_source_review_2026_10_08')", "sources={r['source_id']:r for r in json.loads((base/'sources.json').read_text())}", "path=Path(next(f['absolute_path'] for f in sources['host_mouse_tissue_transcriptome']['verified_files'] if f['name']=='E-MTAB-3579-mouse-tissue-tpm.tsv'))", "comments=[]", "with path.open() as stream:", "    for _ in range(10):", "        line=stream.readline()", "        if not line.startswith('#'):break", "        comments.append(line.strip())", "print('Source header comments',comments)", "d=pd.read_csv(path,sep='\\t',comment='#')", "regions=list(H.FANTOM5_BRAIN)", "print('Individual source minima',d[[*regions,H.FANTOM5_MUSCLE]].min().to_dict())", "print('Mapping receipt comparisons')", "hashes={}", "for species,names in H.UNIPROT_IDMAP.items():", "    for name in names:", "        one=root/H.UNIPROT_ROOT/name", "        other=root/'incoming_2026_09_25/uniprot'/name", "        values={'current':hashlib.sha256(one.read_bytes()).hexdigest(),'earlier':hashlib.sha256(other.read_bytes()).hexdigest() if other.exists() else None}", "        hashes[name]=values", "        print(name,values)", "(base/'mapping_hash_diagnostic.json').write_text(json.dumps(hashes,indent=2)+'\\n')")
nb.code("mapping=H.uniprot_index(str(root),'mouse')['by_ensembl']", "d['host_id']=d['Gene ID'].str.split('.').str[0].map(mapping)", "numeric=d[regions].apply(pd.to_numeric,errors='coerce')", "selected=pd.DataFrame({'host_id':d.host_id,'brain_tpm':numeric.where(numeric>=.5).mean(axis=1),'skeletal_muscle_tpm':pd.to_numeric(d[H.FANTOM5_MUSCLE],errors='coerce').where(lambda x:x>=.5)})", "selected=selected[selected.host_id.notna()].drop_duplicates('host_id').set_index('host_id')", "installed=pd.read_parquet(Path('starplast/data')/O.HOST_TABLES[O.MOUSE]).set_index('host_id')", "diagnostic={'hypothesis':'registry-documented 0.5 cutoff applied per original region before brain averaging; no threshold search','fields':{}}", "for column in ('brain_tpm','skeletal_muscle_tpm'):", "    candidate=selected[column].reindex(installed.index)", "    known=installed[column].notna()", "    measured=candidate.notna()", "    overlap=known&measured", "    diagnostic['fields'][column]={'missing':int((known&~measured).sum()),'extra':int((~known&measured).sum()),'numerical_differences_on_overlap':int(installed.loc[overlap,column].ne(candidate[overlap]).sum()),'tested_overlap':int(overlap.sum())}", "(base/'cutoff_diagnostic.json').write_text(json.dumps(diagnostic,indent=2)+'\\n')", "print(diagnostic)")
